<div class="card table-responsive"><table><thead><tr><th>Expediteur</th><th>Role</th><th>Sujet</th><th>Message</th><th>Date</th></tr></thead><tbody><?php foreach(($messages ?? []) as $m): ?><tr><td><?= htmlspecialchars(($m['prenom'] ?? '') . ' ' . ($m['nom'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($m['sender_role'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($m['subject'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($m['body'], ENT_QUOTES, 'UTF-8') ?></td><td><?= date('d/m/Y H:i', strtotime((string)$m['sent_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div>
